function open(){let d=document.getElementById('m8dlg');if(!d){d=document.createElement('dialog');d.id='m8dlg';d.innerHTML='<style>#m8dlg{width:min(96vw,760px);padding:12px}#m8rows{max-width:100%;margin:auto}.m8row{display:grid;grid-template-columns:82px minmax(80px,1fr) 38px 28px 64px;gap:5px;align-items:center;padding:6px 4px;border-bottom:1px solid rgba(150,170,190,.18);font-size:13px}.m8row button{padding:6px!important;min-height:32px}.m8city{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.m8cnt,.m8st{text-align:center}.m8err{grid-column:1/-1;color:#f2a6a6;white-space:normal}.m8filters{display:flex;gap:6px;margin:8px 0}.m8filters button{flex:1;padding:7px!important;font-size:12px}</style><div class="dialog-head"><div><div class="eyebrow">8. ARŞİV</div><h2>TJK Koşu Sorgulama</h2></div><button id="m8x" class="icon-btn">✕</button></div><div class="panel compact"><div class="grid2"><label>Başlangıç<input id="m8a" type="date"></label><label>Bitiş<input id="m8b" type="date"></label><label>Yıl<select id="m8y"><option value="">Tümü</option></select></label><label>İl<select id="m8c"><option value="">Tümü</option></select></label></div><button id="m8q" class="primary">Listeyi Oluştur</button><button id="m8all" class="primary">Eksikleri Toplu İndir</button><button id="m8stop" class="secondary">Durdur</button><div class="m8filters"><button id="m8showall" class="secondary">Tümü</button><button id="m8showfail" class="secondary">⚠ İndirilemeyenler (0)</button></div><div id="m8sum" class="status">Hazır</div></div><div id="m8rows"></div>';document.body.appendChild(d);let now=new Date(),a=new Date(now.getFullYear(),0,1);m8a.value=a.toISOString().slice(0,10);m8b.value=now.toISOString().slice(0,10);for(let y=now.getFullYear();y>=2000;y--)m8y.add(new Option(y,y));Object.keys(C).sort((a,b)=>a.localeCompare(b,'tr')).forEach(x=>m8c.add(new Option(x,x)));m8x.onclick=()=>d.close();m8q.onclick=async()=>{try{stop=false;fail.clear();m8sum.textContent='Liste hazırlanıyor…';await catalog(m8a.value,m8b.value);await render()}catch(x){m8sum.textContent='⚠ '+x.message}};m8y.onchange=m8c.onchange=render;m8stop.onclick=()=>stop=true;m8showall.onclick=()=>{mode='all';render()};m8showfail.onclick=()=>{mode='failed';render()};m8all.onclick=async()=>{if(busy)return;busy=true;stop=false;fail.clear();let l=filtered(),success=0;for(const r of l){if(stop)break;if(await get(r.key)){success++;continue}try{await dl(r);success++}catch(x){fail.set(r.key,x.message)}m8showfail.textContent='⚠ İndirilemeyenler ('+fail.size+')';m8sum.textContent='Toplu indirme · Başarılı: '+success+' · Hata: '+fail.size;await new Promise(q=>setTimeout(q,350))}busy=false;m8showfail.textContent='⚠ İndirilemeyenler ('+fail.size+')';render()}}d.showModal()}
function install(){let dr=document.getElementById('drawer');if(!dr||document.getElementById('m8btn47'))return;let b=[...dr.querySelectorAll('button')].find(x=>/^8\.\s*Gerçek Yarış Arşivi/i.test(String(x.textContent||'').trim()));if(!b)return;let sub=document.createElement('button');sub.id='m8btn47';sub.type='button';sub.textContent='TJK Koşu Sorgulama / İndirme';sub.style.marginLeft='18px';sub.style.width='calc(100% - 18px)';sub.onclick=x=>{x.preventDefault();x.stopPropagation();try{window.closeDrawer?.()}catch{}setTimeout(open,0)};dr.appendChild(sub);const place=()=>{let host=[...dr.querySelectorAll('button')].find(x=>/^8\.\s*Gerçek Yarış Arşivi/i.test(String(x.textContent||'').trim()));if(host&&sub.previousElementSibling!==host)host.insertAdjacentElement('afterend',sub)};place();setTimeout(place,80);setTimeout(place,250)}
document.addEventListener('click',x=>{if(x.target?.id==='menuBtn')setTimeout(install,0)},{passive:true});window.ATM8F47={open,install};console.info('[AT AI] F60.94.31.47 compact Menu8 active; startup I/O=0');
